function update(){if(!battle||scene!=='battle'||battle.done)return;
	  if(battle.role==='replay'){while(replayIndex<replayQueue.length&&replayQueue[replayIndex].t<=battle.tick){let c=replayQueue[replayIndex++];if(c.kind==='deploy')battle.deploy(c.type,c.x,false,c.level||1);else if(c.kind==='land')battle.landBoat(c.type,c.count,c.x,c.index,c.level||1,false,c.z,c.capacity);else battle.useSkill(c.kind,c.x,c.z,c.id,false,c.aimQuality??1,c.heading)}}
	  else while(autoQueue.length&&autoQueue[0].t<=battle.tick){let command=autoQueue.shift();deployBoat(command.index,command.x,MAP.beachZ+.45,true)}
  battle.step();for(let landing of battle.landings){let rate=.985+(landing.index%3)*.015;if(battle.tick===landing.start+1)playSfx('landing_engine',sfxVolume.landing_engine,rate);if(battle.tick===landing.release-13){playSfx('landing_impact',sfxVolume.landing_impact,rate);playSfx('splash',sfxVolume.splash,rate)}if(battle.tick===landing.release-8)playSfx('ramp',sfxVolume.ramp,rate);if(battle.tick===landing.release+1)playSfx('steps',sfxVolume.steps,rate)}if(battle.events.some(e=>e.kind==='blast'&&e.at===battle.tick))eventTone('explosion');let launching=battle.events.find(e=>e.kind==='launch'&&e.ttl===13);if(launching)eventTone('combat-'+launching.weapon);
  let combat=battle.events.find(e=>(e.kind==='hit'||e.kind==='shot')&&e.at===battle.tick);if(combat)eventTone('combat-'+combat.weapon);
  if(!battle.done&&battle.role==='attack'&&battle.tick>240&&battle.units.every(u=>u.hp<=0||u.type==='medic')&&battle.landings.every(l=>l.released)&&manifest.every(v=>v.used||v.count<=0)&&!battle.gunboatShells.length&&!autoQueue.length){battle.done=true;battle.outcome='失败';battle.cause='部队全灭或无法继续出击'}
  if(battle.role==='replay'&&!battle.done&&battle.tick>=battle.stopTick){battle.done=true;battle.outcome=battle.expectedOutcome;battle.cause='战斗记录结束'}
  if(battle.done)finish();
}
